module serializer (
    input clk,
    input rst,
    input [7:0] data_in,
    input start,
    output reg serial_out,
    output reg done
);
    reg [2:0] count; // 3-bit counter for 8 bits
    reg [7:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count <= 3'b000;
            serial_out <= 0;
            done <= 0;
            shift_reg <= 8'b0;
        end else if (start) begin
            shift_reg <= data_in;
            count <= 3'b000;
            done <= 0;
        end else if (count < 3'd8) begin
            serial_out <= shift_reg[7]; // Output the MSB
            shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left
            count <= count + 1;
        end else begin
            done <= 1; // Serialization complete
        end
    end
endmodule

