module PLL #(  
    parameter DIV_FACTOR = 4,  
    parameter GAIN = 2  
)(  
    input wire clk_ref,  
    input wire rst,  
    output reg clk_out  
);  
    reg [31:0] counter;  
    reg clk_div;  
    reg [31:0] phase_err;  

    always @(posedge clk_ref or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            clk_out <= 0;  
            clk_div <= 0;  
            phase_err <= 0;  
        end else begin  
            counter <= counter + 1;  
            if (counter >= DIV_FACTOR) begin  
                clk_div <= ~clk_div;  
                counter <= 0;  
            end  
            phase_err <= (clk_div ? GAIN : 0);  
            clk_out <= clk_div;  
        end  
    end  
endmodule

