module cordic (
    input clk,
    input rst,
    input [31:0] angle, // Angle in radians (fixed-point)
    input start,
    output reg [31:0] sine,
    output reg [31:0] cosine,
    output reg done
);
    parameter N = 16; // Number of iterations
    reg [31:0] x, y, z;
    reg [4:0] i;
    reg [31:0] angle_table [0:N-1];

    initial begin
        angle_table[0] = 32'h3F19999A; // atan(2^0)
        angle_table[1] = 32'h3E4CCCCD; // atan(2^-1)
        angle_table[2] = 32'h3D89FBCB; // atan(2^-2)
        angle_table[3] = 32'h3C8F5C29; // atan(2^-3)
        angle_table[4] = 32'h3C23D70A; // atan(2^-4)
        angle_table[5] = 32'h3B8F8D8B; // atan(2^-5)
        angle_table[6] = 32'h3B1A6264; // atan(2^-6)
        angle_table[7] = 32'h3A8CFCF8; // atan(2^-7)
        angle_table[8] = 32'h3A0E1B3E; // atan(2^-8)
        angle_table[9] = 32'h39B2E5A0; // atan(2^-9)
        angle_table[10] = 32'h398A1B40; // atan(2^-10)
        angle_table[11] = 32'h397BFA1A; // atan(2^-11)
        angle_table[12] = 32'h396DF078; // atan(2^-12)
        angle_table[13] = 32'h3961E2F6; // atan(2^-13)
        angle_table[14] = 32'h395A9E58; // atan(2^-14)
        angle_table[15] = 32'h39553C3E; // atan(2^-15)
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x <= 32'h00010000; // Initial x = 1.0
            y <= 32'h00000000; // Initial y = 0.0
            z <= angle; // Input angle
            i <= 0;
            done <= 0;
            sine <= 0;
            cosine <= 0;
        end else if (start && !done) begin
            if (i < N) begin
                if (z < 0) begin
                    // Rotate counter-clockwise
                    x <= x + (y >>> i);
                    y <= y - (x >>> i);
                    z <= z + angle_table[i];
                end else begin
                    // Rotate clockwise
                    x <= x - (y >>> i);
                    y <= y + (x >>> i);
                    z <= z - angle_table[i];
                end
                i <= i + 1;
            end else begin
                done <= 1;
                sine <= y;
                cosine <= x;
            end
        end
    end
endmodule

