module PISO (
    input wire clk,
    input wire load,
    input wire shift,
    input wire [7:0] parallel_in,
    output reg serial_out,
    output reg ready
);
    reg [7:0] shift_reg;
    reg [3:0] bit_count;

    always @(posedge clk) begin
        if (load) begin
            shift_reg <= parallel_in;
            bit_count <= 4'd8;
            ready <= 1'b0;
        end else if (shift && bit_count > 0) begin
            serial_out <= shift_reg[7];
            shift_reg <= {shift_reg[6:0], 1'b0};
            bit_count <= bit_count - 1;
            if (bit_count == 1) ready <= 1'b1; // Indicate output is complete
        end
    end
endmodule

