module dma_controller (
    input wire clk,
    input wire reset,
    input wire [2:0] channel_select, // 3 bits for 8 channels
    input wire start,
    output reg done
);
    reg [2:0] current_channel;
    reg transferring;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_channel <= 3'b000;
            transferring <= 1'b0;
            done <= 1'b0;
        end else if (start && !transferring) begin
            current_channel <= channel_select;
            transferring <= 1'b1;
            done <= 1'b0;
        end else if (transferring) begin
            // Assume transfer completes after one clock cycle
            done <= 1'b1;
            transferring <= 1'b0;
        end
    end
endmodule

