module sample_rate_converter(
    input clk_in,
    input reset,
    input [3:0] data_in,
    output reg [3:0] data_out,
    output reg valid
);
    reg [1:0] count; // To generate 2x output samples

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            count <= 2'b00;
            data_out <= 4'b0000;
            valid <= 1'b0;
        end else begin
            if (count == 2'b00) begin
                data_out <= data_in; // First sample
                valid <= 1'b1;
                count <= count + 1;
            end else if (count == 2'b01) begin
                data_out <= data_in * 2; // Second sample
                valid <= 1'b1;
                count <= count + 1;
            end else begin
                valid <= 1'b0; // No valid output
                count <= 2'b00; // Reset count
            end
        end
    end
endmodule

