module VCO(
    input wire clk,
    input wire rst,
    input wire [7:0] ctrl_voltage,
    output reg clk_out
);
    reg [31:0] counter;
    reg [31:0] threshold;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 0;
            clk_out <= 0;
            threshold <= 0;
        end else begin
            // Calculate threshold based on control voltage
            threshold <= 1000000 / (1 + ctrl_voltage); // Period in ns

            if (counter >= threshold) begin
                clk_out <= ~clk_out;
                counter <= 0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
endmodule

