module dma_controller (  
    input wire clk,  
    input wire reset,  
    input wire channel1_req,  
    input wire channel2_req,  
    output reg channel1_ack,  
    output reg channel2_ack,  
    output reg [7:0] data_out1,  
    output reg [7:0] data_out2,  
    input wire [7:0] src_addr1,  
    input wire [7:0] src_addr2,  
    output reg [7:0] dst_addr1,  
    output reg [7:0] dst_addr2,  
    input wire start_transfer1,  
    input wire start_transfer2  
);  

    reg [1:0] state;  
    parameter IDLE = 2'b00, TRANSFER1 = 2'b01, TRANSFER2 = 2'b10;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            channel1_ack <= 0;  
            channel2_ack <= 0;  
        end  
        else begin  
            case (state)  
                IDLE: begin  
                    if (start_transfer1 && channel1_req) begin  
                        state <= TRANSFER1;  
                        channel1_ack <= 1;  
                    end  
                    else if (start_transfer2 && channel2_req) begin  
                        state <= TRANSFER2;  
                        channel2_ack <= 1;  
                    end  
                end  
                TRANSFER1: begin  
                    data_out1 <= src_addr1;  
                    dst_addr1 <= data_out1;  
                    channel1_ack <= 0;  
                    state <= IDLE;  
                end  
                TRANSFER2: begin  
                    data_out2 <= src_addr2;  
                    dst_addr2 <= data_out2;  
                    channel2_ack <= 0;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

