module uart_transmitter(  
    input wire clk,  
    input wire rst,  
    input wire tx_en,  
    input wire [7:0] data_in,  
    output reg tx  
);  
    reg [3:0] bit_index;  
    reg [9:0] shift_reg; // 1 start bit + 8 data bits + 1 stop bit  
    reg sending;  
    parameter IDLE = 1'b0, SENDING = 1'b1;  
    reg state;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            tx <= 1;  // TX idle state is high  
            state <= IDLE;  
            bit_index <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (tx_en) begin  
                        shift_reg <= {1'b1, data_in, 1'b0}; // start bit, data, stop bit  
                        bit_index <= 0;  
                        state <= SENDING;  
                    end  
                end  
                SENDING: begin  
                    tx <= shift_reg[bit_index];  
                    bit_index <= bit_index + 1;  
                    if (bit_index == 10) begin  
                        state <= IDLE;  
                    end  
                end  
            endcase  
        end  
    end  
endmodule

