module ethernet_mac_controller(
    input wire clk,
    input wire reset,
    input wire start_send,
    input wire start_receive,
    output reg [1:0] state, // 00: IDLE, 01: SENDING, 10: RECEIVING
    output reg send_success,
    output reg receive_success
);

    // State encoding
    parameter IDLE = 2'b00;
    parameter SENDING = 2'b01;
    parameter RECEIVING = 2'b10;

    // State register
    reg [1:0] next_state;

    // Sequential logic: state transition
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Combinational logic: next state and outputs
    always @* begin
        next_state = state;
        send_success = 0;
        receive_success = 0;

        case (state)
            IDLE: begin
                if (start_send) begin
                    next_state = SENDING;
                end else if (start_receive) begin
                    next_state = RECEIVING;
                end
            end
            SENDING: begin
                send_success = 1; // Assume sending is always successful for simplicity
                next_state = IDLE; // Go back to IDLE after sending
            end
            RECEIVING: begin
                receive_success = 1; // Assume receiving is always successful for simplicity
                next_state = IDLE; // Go back to IDLE after receiving
            end
        endcase
    end
endmodule

