module frequency_divider (
    input wire clk,
    input wire enable,
    output reg divided_clk
);
    reg [3:0] counter;

    always @(posedge clk) begin
        if (enable) begin
            counter <= counter + 1;
            if (counter == 4'b1111) begin
                divided_clk <= ~divided_clk;
                counter <= 0;
            end
        end
    end

    initial begin
        divided_clk = 0;
        counter = 0;
    end
endmodule

