module butterworth_filter (
    input clk,
    input rst,
    input signed [3:0] x,
    output reg signed [3:0] y
);
    reg signed [3:0] x_prev;
    reg signed [3:0] y_prev;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            x_prev <= 0;
            y_prev <= 0;
            y <= 0;
        end else begin
            y <= (x + x_prev + (y_prev <<< 1)) >> 2; // Coefficients for Butterworth filter
            x_prev <= x;
            y_prev <= y;
        end
    end
endmodule

