    reg [1:0] state;

    localparam IDLE = 2'b00;
    localparam SEND = 2'b01;
    localparam DONE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sclk <= 1'b0;
            mosi <= 1'b0;
            cs <= 1'b1;
            bit_count <= 0;
            shift_reg <= 0;
            done <= 1'b0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    cs <= 1'b1; // chip select high
                    done <= 1'b0;
                    if (start) begin
                        cs <= 1'b0; // chip select low
                        case (bit_length)
                            2'b00: shift_reg <= data_in[7:0]; // 8 bits
                            2'b01: shift_reg <= data_in[15:0]; // 16 bits
                            2'b10: shift_reg <= data_in[31:0]; // 32 bits
                        endcase
                        bit_count <= 0;
                        state <= SEND;
                    end
                end
                SEND: begin
                    if (bit_count < (bit_length == 2'b00 ? 8 : (bit_length == 2'b01 ? 16 : 32))) begin
                        sclk <= ~sclk; // toggle clock
                        if (sclk) begin
                            mosi <= shift_reg[31]; // transmit the MSB
                            shift_reg <= {shift_reg[30:0], 1'b0}; // shift left
                            bit_count <= bit_count + 1;
                        end
                    end else begin
                        state <= DONE;
                    end
                end
                DONE: begin
                    cs <= 1'b1; // chip select high
                    done <= 1'b1;
                    state <= IDLE;
                end
            endcase
        end
    end
endmodule

