module uart_tx(
    input wire clk,
    input wire reset,
    input wire start_tx,
    input wire [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE = 9600;
    parameter CLOCK_FREQ = 50000000; // 50 MHz clock
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [15:0] clk_count;
    reg [8:0] shift_reg;
    reg sending;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx <= 1; // idle state
            busy <= 0;
            bit_index <= 0;
            clk_count <= 0;
            sending <= 0;
        end else begin
            if (start_tx && !busy) begin
                busy <= 1;
                shift_reg <= {1'b1, data_in, 1'b0}; // stop bit, data, start bit
                bit_index <= 0;
                clk_count <= 0;
                sending <= 1;
            end

            if (sending) begin
                clk_count <= clk_count + 1;
                if (clk_count >= BIT_PERIOD - 1) begin
                    clk_count <= 0;
                    tx <= shift_reg[bit_index];
                    if (bit_index < 9) begin
                        bit_index <= bit_index + 1;
                    end else begin
                        busy <= 0;
                        sending <= 0;
                    end
                end
            end
        end
    end
endmodule

