module serializer (
    input wire clk,
    input wire rst,
    input wire [15:0] parallel_in,
    output reg serial_out
);
    reg [3:0] bit_counter; // To count the bits sent
    initial begin
        bit_counter = 0;
        serial_out = 0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            bit_counter <= 0;
            serial_out <= 0;
        end else if (bit_counter < 16) begin
            serial_out <= parallel_in[15 - bit_counter]; // Send MSB first
            bit_counter <= bit_counter + 1;
        end else begin
            serial_out <= 0; // Hold the last value after 16 bits
        end
    end
endmodule

