module instruction_pipeline (
    input clk,
    input reset,
    input [31:0] instruction, // Input instruction
    output reg [31:0] wb_output // Output from Write Back stage
);
    reg [31:0] if_stage, id_stage, ex_stage, mem_stage;
    reg [1:0] stall; // 00: No stall, 01: Stall ID, 10: Stall EX
    reg [31:0] instruction_buffer; // Buffer for instructions

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            if_stage <= 0;
            id_stage <= 0;
            ex_stage <= 0;
            mem_stage <= 0;
            wb_output <= 0;
            instruction_buffer <= 0;
            stall <= 0;
        end else begin
            // Pipeline stages operation
            if (stall == 2'b00) begin
                // Standard operation
                if_stage <= instruction;
                id_stage <= if_stage;
                ex_stage <= id_stage;
                mem_stage <= ex_stage;
                wb_output <= mem_stage;
            end else if (stall == 2'b01) begin
                // Stall ID, hold ID stage
                id_stage <= id_stage;
                ex_stage <= id_stage;
                mem_stage <= ex_stage;
                wb_output <= mem_stage;
            end else if (stall == 2'b10) begin
                // Stall EX, hold EX stage
                ex_stage <= ex_stage;
                mem_stage <= ex_stage;
                wb_output <= mem_stage;
            end
            // Determine stall conditions (example condition for simplicity)
            if (instruction_buffer == id_stage) begin
                stall <= 2'b01; // Stall ID
            end else if (instruction_buffer == ex_stage) begin
                stall <= 2'b10; // Stall EX
            end else begin
                stall <= 2'b00; // No stall
            end
            instruction_buffer <= instruction; // Update instruction buffer
        end
    end
endmodule

