module pll_8x (  
    input wire clk_in,  
    input wire reset,  
    output reg clk_out,  
    output reg locked  
);  
    reg [2:0] count;  
    reg [2:0] state;  
    localparam IDLE = 3'b000,  
               LOCKED = 3'b001,  
               UNLOCKED = 3'b010;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            count <= 3'b000;  
            state <= UNLOCKED;  
            clk_out <= 0;  
            locked <= 0;  
        end else begin  
            if (state == UNLOCKED) begin  
                count <= count + 1;  
                if (count == 3'b111) begin  
                    clk_out <= ~clk_out;  
                    count <= 3'b000;  
                    state <= LOCKED;  
                    locked <= 1;  
                end  
            end else if (state == LOCKED) begin  
                clk_out <= clk_out;  
                // Additional logic can be added here for locked state  
            end  
        end  
    end  
endmodule

